create or replace function public.get_or_create_private_chat(p_friend uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare g uuid; k text; a text; b text; begin if not public.is_chat_friend(auth.uid(),p_friend) then raise exception 'You can only message an accepted friend'; end if; if auth.uid()::text<p_friend::text then a:=auth.uid()::text;b:=p_friend::text;else a:=p_friend::text;b:=auth.uid()::text;end if; k:='private:'||a||':'||b; select id into g from public.chat_groups where direct_key=k limit 1; if g is null then insert into public.chat_groups(name,created_by,kind,direct_key) values('Private chat',auth.uid(),'private',k) returning id into g; insert into public.chat_group_members(group_id,user_id) values(g,auth.uid()),(g,p_friend) on conflict do nothing; end if; return g; end; $$; grant execute on function public.get_or_create_private_chat(uuid) to authenticated;
